(()=>{const names=new Proxy({},{get:(_,key)=>key});let ticking=false;const key=()=> 'frame-scene-upscale-'+data.project_id;function state(){try{return JSON.parse(localStorage.getItem(key())||'null')||{target:2560,selected:{},items:[]};}catch{return{target:2560,selected:{},items:[]};}}function store(s){localStorage.setItem(key(),JSON.stringify(s));}function assets(){return(data.scenes||[]).flatMap(scene=>{const keys=[...new Set(['master',...(scene.camera_anchors||[]).map(a=>a.id),...(scene.sceneVersions||[]).map(v=>v.view_key||'master')])];return keys.flatMap(key=>{const v=selectedSceneVersion(scene,key);if(!v?.image_url)return[];const angle=key==='master'?'主图':key+' · '+((scene.camera_anchors||[]).find(a=>a.id===key)?.description||'机位');return[{scene_id:String(scene.id||scene.scene_id),name:scene.name,angle,source:v.image_url,width:v.width,height:v.height,id:String(scene.id||scene.scene_id)+':'+key}];});});}async function reloadProject(){const remote=await frontFetch('/api/project?id='+encodeURIComponent(data.project_id));if(JSON.stringify(data)===lastDiskData&&!diskBusy&&!diskConflict){data=remote.project;diskRevision=remote.revision;lastDiskData=JSON.stringify(data);browserSave();render();}else toast('高清结果已保存，请完成当前编辑后刷新查看');}function draw(){if(tab!==1)return;const anchor=document.querySelector('#panel .section-head');if(!anchor)return;document.querySelector('#sceneUpscaleBatch')?.remove();const s=state(),list=assets(),box=document.createElement('section');box.id='sceneUpscaleBatch';box.className='card';box.style.margin='12px 0 18px';box.innerHTML='<h3>场景图片批量放大</h3><p class="subtle">包含所有场景主图和已生成机位。已达到目标尺寸自动跳过；完成后替换对应图片，原图保留历史版本。</p><div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap"><label style="width:auto">目标尺寸<select data-target><option value="1920">1080P</option><option value="2560">2.5K</option><option value="3840">4K</option></select></label><label style="display:flex;align-items:center;gap:8px;width:auto"><input type="checkbox" data-all style="width:18px;flex:none">全选</label></div><div data-assets style="display:flex;gap:10px;flex-wrap:wrap;margin:14px 0">'+list.map(x=>'<label style="display:inline-flex;align-items:center;gap:8px;width:auto;border:1px solid #3d514b;border-radius:8px;padding:10px"><input data-asset="'+esc(x.id)+'" type="checkbox" '+(s.selected[x.id]!==false?'checked':'')+' style="width:18px;flex:none">'+esc(x.name+' · '+names[x.angle])+'</label>').join('')+'</div><button class="primary" data-everyone>放大所有场景</button> <button data-start>放大所选图片</button> <button data-stop>停止放大</button><p data-status class="subtle"></p>';anchor.after(box);box.querySelector('[data-target]').value=s.target;box.querySelector('[data-target]').onchange=e=>{const v=state();v.target=Number(e.target.value);store(v);};const all=box.querySelector('[data-all]'),chosen=list.filter(x=>s.selected[x.id]!==false);all.checked=!!list.length&&chosen.length===list.length;all.indeterminate=!!chosen.length&&chosen.length<list.length;all.onchange=e=>{const v=state();for(const x of list)v.selected[x.id]=e.target.checked;store(v);draw();};box.querySelectorAll('[data-asset]').forEach(el=>el.onchange=()=>{const v=state();v.selected[el.dataset.asset]=el.checked;store(v);draw();});box.querySelector('[data-everyone]').disabled=s.running||!list.length;box.querySelector('[data-everyone]').onclick=()=>{const v=state();for(const x of assets())v.selected[x.id]=true;store(v);draw();document.querySelector('#sceneUpscaleBatch [data-start]')?.click();};box.querySelector('[data-start]').disabled=s.running||!chosen.length;box.querySelector('[data-stop]').disabled=!s.running;box.querySelector('[data-target]').disabled=!!s.running;box.querySelector('[data-start]').onclick=async()=>{try{await ensureProjectSaved();if((data.scenes||[]).some(c=>Object.values(c.jobs||{}).some(j=>sceneBusy(j))))throw Error('请先等待场景生成完成');const v=state();v.project_id=data.project_id;v.items=assets().filter(x=>v.selected[x.id]!==false).map(x=>({...x,status:Math.max(x.width||0,x.height||0)>=v.target?'skipped':'queued'}));v.running=true;v.started_at=Date.now();store(v);draw();tick();}catch(e){toast(e.message);}};box.querySelector('[data-stop]').onclick=async()=>{const v=state();v.running=false;for(const i of v.items)if(i.status==='queued')i.status='cancelled';store(v);const current=v.items.find(i=>i.status==='running');if(current?.job_id)try{await frontFetch('/api/tools/jobs/'+current.job_id+'/cancel',{});current.status='cancelled';store(v);}catch(e){toast(e.message);}draw();};const done=s.items.filter(i=>['completed','skipped'].includes(i.status)).length,current=s.items.find(i=>i.status==='running');box.querySelector('[data-status]').textContent=s.items.length?'已完成 '+done+'/'+s.items.length+(current?' · '+current.name+' · '+names[current.angle]+' · '+(current.phase||'生成中'):'')+(s.running?' · 请保持页面打开，刷新后可继续':' · 已结束')+(s.items.some(i=>i.error)?' · '+s.items.filter(i=>i.error).map(i=>i.name+'：'+i.error).join('；'):''):'选择一个或多个视图，也可全选全部场景及机位图片。';}
async function tick(){if(ticking||typeof data==='undefined'||!data.project_id)return;let s=state();if(!s.running)return;ticking=true;const project=data.project_id;try{let item=s.items.find(i=>i.status==='running');if(item){const j=await frontFetch('/api/tools/jobs/'+item.job_id);if(data.project_id!==project)return;s=state();if(!s.running)return;item=s.items.find(i=>i.job_id===j.id);item.phase=j.progress?.label||j.status;if(['completed','failed','cancelled'].includes(j.status)){item.status=j.status;item.error=j.error||j.apply_error;store(s);if(j.status==='completed')await reloadProject();}else{store(s);return;}}s=state();item=s.items.find(i=>i.status==='queued');if(!item){s.running=false;store(s);return;}if(JSON.stringify(data)!==lastDiskData||diskBusy||diskConflict)return;const jobs=await frontFetch('/api/tools/jobs');if(jobs.some(j=>['preparing','queued','running','waiting','saving'].includes(j.status)))return;const response=await fetch(item.source);if(!response.ok)throw Error('原图不可用');const blob=await response.blob(),image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});const bitmap=await createImageBitmap(blob);const width=bitmap.width,height=bitmap.height;bitmap.close();if(!state().running)return;if(Math.max(width,height)>=s.target){item.status='skipped';item.phase='已达到目标尺寸，已跳过';store(s);return;}const upload=await frontFetch('/api/tools/upload',{image});const j=await frontFetch('/api/tools/jobs',{kind:'image-upscale',upload_id:upload.id,source_width:width,source_height:height,upscale_target:s.target,port:Number(localStorage.getItem('frame-comfy-port')||8188),upscale_binding:{project_id:project,scene_id:item.scene_id,source:item.source}});if(!state().running){await frontFetch('/api/tools/jobs/'+j.id+'/cancel',{});return;}item.job_id=j.id;item.status='running';store(s);}catch(e){s=state();const i=s.items.find(i=>i.status==='running'||i.status==='queued');if(i){i.status='failed';i.error=e.message;}store(s);}finally{ticking=false;if(tab===1)draw();}}
const prior=renderScenes;renderScenes=function(){prior();draw();};setInterval(()=>{if(navigator.locks)navigator.locks.request('scene-image-upscale',{ifAvailable:true},lock=>lock?tick():undefined);else tick();},3000);render();})();